   131  bool SnoopFileReaderDevice::open()
   132  {
   133          m_NumOfPacketsRead = 0;
   134          m_NumOfPacketsNotParsed = 0;
   135
   136          m_snoopFile.open(m_FileName.c_str(), std::ifstream::binary);
   137          if (!m_snoopFile.is_open())
   138          {
   139                  PCPP_LOG_ERROR("Cannot open snoop reader device for filename '" << m_FileName << "'");
   140                  m_snoopFile.close();
   141                  return false;
   142          }
   143
   144          snoop_file_header_t snoop_file_header;
   145          m_snoopFile.read((char*)&snoop_file_header, sizeof(snoop_file_header_t));
   146          if (!m_snoopFile)
   147          {
   148                  PCPP_LOG_ERROR("Cannot read snoop file header for '" << m_FileName << "'");
   149                  m_snoopFile.close();
   150                  return false;
   151          }
   152
   153          if(be64toh(snoop_file_header.identification_pattern) != 0x736e6f6f70000000 && be32toh(snoop_file_header.version_number) == 2)
   154                  return false;
   155
   156          // From https://datatracker.ietf.org/doc/html/rfc1761
   157          static const pcpp::LinkLayerType snoop_encap[] = {
   158                  LINKTYPE_ETHERNET,      /* IEEE 802.3 */
   159                  LINKTYPE_NULL,          /* IEEE 802.4 Token Bus */
   160                  LINKTYPE_IEEE802_5,     /* IEEE 802.5 */
   161                  LINKTYPE_NULL,          /* IEEE 802.6 Metro Net */
   162                  LINKTYPE_ETHERNET,      /* Ethernet */
   163                  LINKTYPE_C_HDLC,        /* HDLC */
   164                  LINKTYPE_NULL,          /* Character Synchronous, e.g. bisync */
   165                  LINKTYPE_NULL,          /* IBM Channel-to-Channel */
   166                  LINKTYPE_FDDI           /* FDDI */
   167          };
   168          uint32_t datalink_type = be32toh(snoop_file_header.datalink_type);
   169          if (datalink_type > ARRAY_SIZE(snoop_encap) - 1)
   170          {
   171                  PCPP_LOG_ERROR("Cannot read data link type for '" << m_FileName << "'");
   172                  m_snoopFile.close();
   173                  return false;
   174          }
   175
   176          m_PcapLinkLayerType = snoop_encap[datalink_type];
   177
   178          PCPP_LOG_DEBUG("Successfully opened file reader device for filename '" << m_FileName << "'");
   179          m_DeviceOpened = true;
   180          return true;
   430  }
