    33  void EthLayer::parseNextLayer()
    34  {
    35          if (m_DataLen <= sizeof(ether_header))
    36                  return;
    37
    38          ether_header* hdr = getEthHeader();
    39          uint8_t* payload = m_Data + sizeof(ether_header);
    40          size_t payloadLen = m_DataLen - sizeof(ether_header);
    41
    42          switch (be16toh(hdr->etherType))
    43          {
    44          case PCPP_ETHERTYPE_IP:
    45                  m_NextLayer = IPv4Layer::isDataValid(payload, payloadLen)
    46                          ? static_cast<Layer*>(new IPv4Layer(payload, payloadLen, this, m_Packet))
    47                          : static_cast<Layer*>(new PayloadLayer(payload, payloadLen, this, m_Packet));
    48                  break;
    49          case PCPP_ETHERTYPE_IPV6:
    50                  m_NextLayer = IPv6Layer::isDataValid(payload, payloadLen)
    51                          ? static_cast<Layer*>(new IPv6Layer(payload, payloadLen, this, m_Packet))
    52                          : static_cast<Layer*>(new PayloadLayer(payload, payloadLen, this, m_Packet));
    53                  break;
    54          case PCPP_ETHERTYPE_ARP:
    55                  m_NextLayer = new ArpLayer(payload, payloadLen, this, m_Packet);
    56                  break;
    57          case PCPP_ETHERTYPE_VLAN:
    58          case PCPP_ETHERTYPE_IEEE_802_1AD:
    59                  m_NextLayer = new VlanLayer(payload, payloadLen, this, m_Packet);
    60                  break;
    61          case PCPP_ETHERTYPE_PPPOES:
    62                  m_NextLayer = PPPoESessionLayer::isDataValid(payload, payloadLen)
    63                          ? static_cast<Layer*>(new PPPoESessionLayer(payload, payloadLen, this, m_Packet))
    64                          : static_cast<Layer*>(new PayloadLayer(payload, payloadLen, this, m_Packet));
    65                  break;
    66          case PCPP_ETHERTYPE_PPPOED:
    67                  m_NextLayer = PPPoEDiscoveryLayer::isDataValid(payload, payloadLen)
    68                          ? static_cast<Layer*>(new PPPoEDiscoveryLayer(payload, payloadLen, this, m_Packet))
    69                          : static_cast<Layer*>(new PayloadLayer(payload, payloadLen, this, m_Packet));
    70                  break;
    71          case PCPP_ETHERTYPE_MPLS:
    72                  m_NextLayer = new MplsLayer(payload, payloadLen, this, m_Packet);
    73                  break;
    74          case PCPP_ETHERTYPE_WAKE_ON_LAN:
    75                  m_NextLayer = WakeOnLanLayer::isDataValid(payload, payloadLen)
    76                          ? static_cast<Layer*>(new WakeOnLanLayer(payload, payloadLen, this, m_Packet))
    77                          : static_cast<Layer*>(new PayloadLayer(payload, payloadLen, this, m_Packet));
    78                  break;
    79          default:
    80                  m_NextLayer = new PayloadLayer(payload, payloadLen, this, m_Packet);
    81          }
    82  }
